                if key in seen:
                    continue
                seen.add(key)
                span = {"text": docket}
                if page_no is not None:
                    span["page_no"] = page_no
                if line_no is not None:
                    span["line_no"] = line_no
                if text:
                    span["context"] = text
                spans.append(span)

        return spans
    except Exception:
